// Tessellates the Penn Elcom H1105 handle's STEP model (build/assets/penn-elcom-h1105.step, SolidWorks AP203, mm) into
// the compact mesh the 3D view draws (src/data/meshes/h1105.ts). Run it after changing the STEP file or the settings
// below (`vp run handle-mesh`; LIN and ANG override the deflections to try others); the page only ever reads the
// generated file, so the build needs no CAD tooling.
//
// The model: the flange 220 × 162 mm, 5 mm thick (z 0..5, its outside face at z = 5), the recess body down to
// z = −58; the 220 mm side mounts vertical. occt-import-js (OpenCascade compiled to wasm, a dev dependency) meshes
// each face to LINEAR_DEFLECTION_MM; the vertices are then welded on a QUANT_MM grid, which drops the duplicate
// vertices along the face seams and collapses slivers, and stored as integers of that grid.
import fs from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const STEP = new URL("./assets/penn-elcom-h1105.step", import.meta.url);
const OUT = new URL("../src/data/meshes/h1105.ts", import.meta.url);
/** Largest gap between the mesh and the true surface, mm. */
const LINEAR_DEFLECTION_MM = Number(process.env.LIN ?? 2);
/** Largest angle between neighboring facets on a curve, radians. */
const ANGULAR_DEFLECTION = Number(process.env.ANG ?? 0.8);
/** The weld grid and the stored unit, mm. */
const QUANT_MM = 0.5;

const occt = await require("occt-import-js")();
const res = occt.ReadStepFile(new Uint8Array(fs.readFileSync(STEP)), {
  linearUnit: "millimeter",
  linearDeflectionType: "absolute_value",
  linearDeflection: LINEAR_DEFLECTION_MM,
  angularDeflection: ANGULAR_DEFLECTION,
});
if (!res.success || !res.meshes.length) throw new Error("the STEP file didn't read");

// weld every mesh's vertices on the grid, drop the triangles that collapse
const key = new Map();
const pos = [];
const idx = [];
let inTris = 0;
for (const m of res.meshes) {
  const p = m.attributes.position.array;
  const ids = [];
  for (let i = 0; i < p.length; i += 3) {
    const q = [p[i], p[i + 1], p[i + 2]].map((v) => Math.round(v / QUANT_MM));
    const k = q.join();
    let id = key.get(k);
    if (id === undefined) {
      id = pos.length / 3;
      key.set(k, id);
      pos.push(...q);
    }
    ids.push(id);
  }
  const ix = m.index.array;
  inTris += ix.length / 3;
  for (let i = 0; i < ix.length; i += 3) {
    const [a, b, c] = [ids[ix[i]], ids[ix[i + 1]], ids[ix[i + 2]]];
    if (a !== b && b !== c && a !== c) idx.push(a, b, c);
  }
}
// the recess body's outline at the panel (every vertex under the flange's back face): the hole the 3D view opens
const body = [0, 1].map((k) =>
  pos.filter((_, i) => i % 3 === k && pos[i - k + 2] * QUANT_MM < -0.5),
);
const holeLo = body.map((a) => Math.min(...a) * QUANT_MM);
const holeHi = body.map((a) => Math.max(...a) * QUANT_MM);
const lo = [0, 1, 2].map((k) => Math.min(...pos.filter((_, i) => i % 3 === k)) * QUANT_MM);
const hi = [0, 1, 2].map((k) => Math.max(...pos.filter((_, i) => i % 3 === k)) * QUANT_MM);

const line = (a) => {
  const out = [];
  for (let i = 0; i < a.length; i += 24) out.push(`    ${a.slice(i, i + 24).join(",")},`);
  return out.join("\n");
};
const src = `// Generated by build/handle-mesh.mjs from build/assets/penn-elcom-h1105.step: do not edit by hand.
// The Penn Elcom H1105 recessed handle from its STEP model, tessellated to ${LINEAR_DEFLECTION_MM} mm and welded on a
// ${QUANT_MM} mm grid (${pos.length / 3} vertices, ${idx.length / 3} triangles, from ${inTris}). Model axes, mm: x across the flange's
// ${(hi[0] - lo[0]).toFixed(0)} mm, y along its ${(hi[1] - lo[1]).toFixed(0)} mm, z out of the panel (the flange's outside face at z = 5, the recess down to z = ${lo[2].toFixed(0)}).
import type { HardwareMesh } from "../../types";

export const H1105_MESH: HardwareMesh = {
  unitMm: ${QUANT_MM},
  min: [${lo.map((v) => +v.toFixed(2)).join(", ")}],
  max: [${hi.map((v) => +v.toFixed(2)).join(", ")}],
  hole: { min: [${holeLo.join(", ")}], max: [${holeHi.join(", ")}] },
  positions: [
${line(pos)}
  ],
  indices: [
${line(idx)}
  ],
};
`;
fs.mkdirSync(new URL(".", OUT), { recursive: true });
fs.writeFileSync(OUT, src);
console.log(
  `${res.meshes.length} meshes, ${inTris} triangles in; ${pos.length / 3} vertices, ${idx.length / 3} triangles out; ` +
    `bounds ${lo.map((v) => v.toFixed(1)).join()} .. ${hi.map((v) => v.toFixed(1)).join()} mm; recess ${holeLo.join()} .. ${holeHi.join()} mm; ${(src.length / 1024).toFixed(1)} kB`,
);
